from playwright.sync_api import sync_playwright
import fitz
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.goto('http://127.0.0.1:8000/cbse-mcq-page-settings.js');page.set_content('<main id="setup"></main>')
 result=page.evaluate('''async()=>{const {buildMCQPaperFrame}=await import('./cbse-mcq-page-render.js');const {renderMCQPageSetup}=await import('./cbse-mcq-page-setup-view.js');const make=count=>({id:'PREVIEW',classId:'X',subjectName:'English',count,questions:Array.from({length:count},(_,i)=>({id:'QE'+String(i+1).padStart(3,'0'),verbatim:true,stem:Array.from({length:40},(_,j)=>'Question '+i+' line '+j).join('\\n')}))});const selected=make(1);renderMCQPageSetup(document.querySelector('#setup'),{paper:()=>selected});const counts=[];for(const n of [1,2,3,5]){const r=await buildMCQPaperFrame(make(n),{target:1},{fit:false});counts.push({content:r.contentSheetCount,total:r.sheetCount,blank:r.blankPages,blankText:r.pages.querySelector('.paper-duplex-blank')?.textContent||'',blankChildren:r.pages.querySelector('.paper-duplex-blank')?.children.length||0});r.frame.remove();}return {options:document.querySelectorAll('[name=mcq-pdf-pages]').length,counts};}''')
 assert result['options']==0
 assert [r['content'] for r in result['counts']]==[1,2,3,5],result
 assert [r['total'] for r in result['counts']]==[2,2,4,6],result
 assert [r['blank'] for r in result['counts']]==[1,0,1,1]
 assert all(r['blankText']=='' and r['blankChildren']==0 for r in result['counts'])
 # Each named copy must end on an even page, before appending the next student's copy.
 page.evaluate('''async()=>{const {printMCQStudentCopies}=await import('./cbse-mcq-personalised-print.js');new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.matches?.('.mcq-layout-frame'))node.contentWindow.print=()=>{window.printedHTML=node.contentDocument.documentElement.outerHTML;window.printed={count:node.contentDocument.querySelectorAll('.paper-sheet').length,blanks:[...node.contentDocument.querySelectorAll('.paper-sheet')].map((s,i)=>s.dataset.duplexBlank?i:null).filter(i=>i!==null),identities:[...node.contentDocument.querySelectorAll('.paper-student-name')].map(s=>s.textContent)};};}).observe(document.body,{childList:true});const draft={classes:{X:{sections:{a:{name:'A',students:{one:{name:'First Student',subjects:{english:true}},two:{name:'Second Student',subjects:{english:true}}}}}}}};await printMCQStudentCopies({id:'QPE001',classId:'X',subjectId:'english',subjectName:'English',count:1,questions:[{id:'QE001',verbatim:true,stem:'Question\\nA) One\\nB) Two\\nC) Three\\nD) Four'}],copyAssignments:[{studentKey:'X:a:one',token:'1'.repeat(32)},{studentKey:'X:a:two',token:'2'.repeat(32)}]},draft);}''')
 page.wait_for_function('!!window.printed');printed=page.evaluate('window.printed');assert printed['count']==4;assert printed['blanks']==[1,3];assert 'First Student' in printed['identities'][0] and 'Second Student' in printed['identities'][1];pdfpage=b.new_page();pdfpage.set_content(page.evaluate('window.printedHTML'));pdf=fitz.open(stream=pdfpage.pdf(prefer_css_page_size=True),filetype='pdf');assert len(pdf)==4;assert pdf[1].get_text().strip()=='' and pdf[3].get_text().strip()=='';assert 'First Student' in pdf[0].get_text() and 'Second Student' in pdf[2].get_text();b.close()
print('PASS unrestricted 1/2/3/5-page content, truly blank duplex padding and fresh-sheet boundaries between student copies')
